/**
 * Frozen contract shared by the browser (web/) and the backend-for-frontend (server/).
 * Types and constants only: no runtime dependencies.
 *
 * SANDBOX SECURITY MODEL (implemented by the BFF in server/):
 * - Session ids are random UUIDs acting as capabilities. There is no listing endpoint.
 * - Each session owns its own `createServer()` replica bound to 127.0.0.1:0, protected by a
 *   per-session random internal token generated by the BFF. That token is NEVER returned to
 *   the browser.
 * - The BFF only forwards to its own loopback sandboxes: no outbound network, no "Live" mode.
 *   The original deployment host (caja-negra-production-c64f.up.railway.app) is rejected.
 * - Limits are defined by SANDBOX_LIMITS below.
 * - Sessions expire after the idle TTL and their servers are closed.
 * - The browser keeps the session id in memory only (never localStorage/cookies/URL).
 */

export const SANDBOX_LIMITS = {
  /** Across the whole BFF. */
  maxSessions: 20,
  /** Idle expiry. */
  sessionTtlMs: 30 * 60_000,
  /** Body accepted by the BFF from the browser. */
  maxRequestBodyBytes: 4_096,
  /** Body forwarded to the sandboxed replica. */
  maxForwardedBodyBytes: 2_048,
  /** Per forwarded request. */
  sandboxTimeoutMs: 2_000,
  maxRequestsPerMinutePerSession: 120,
} as const;

export type SandboxMethod = "GET" | "POST";

/** `path` must match SANDBOX_PATH_PATTERN. */
export interface SandboxRequest {
  method: SandboxMethod;
  path: string;
  body?: string;
}

export const SANDBOX_PATH_PATTERN = /^\/[A-Za-z0-9_\-/]{0,63}$/;

export interface CreateSessionResponse {
  sessionId: string;
  expiresAt: string;
}

export interface SandboxExchange {
  /** Exchange id (uuid). */
  id: string;
  /** 1-based order within the session. */
  sequence: number;
  request: SandboxRequest;
  status: number;
  xReq: string | null;
  /** Parsed JSON when possible, else raw text. */
  body: unknown;
  durationMs: number;
  /** ISO timestamp. */
  at: string;
}

export interface ExperimentRecord {
  id: number;
  seq: string;
  x_req: number | string | null;
  hipotesis: string;
  request: unknown;
  status: number;
  response: unknown;
  conclusion: string | null;
  method?: string;
  path?: string;
  auth?: string;
}

export interface ExperimentsResponse {
  experiments: ExperimentRecord[];
}

export type BffErrorCode =
  | "INVALID_REQUEST"
  | "PAYLOAD_TOO_LARGE"
  | "SESSION_NOT_FOUND"
  | "SESSION_LIMIT"
  | "RATE_LIMITED"
  | "SANDBOX_TIMEOUT"
  | "NOT_FOUND"
  | "INTERNAL"
  | "NOT_IMPLEMENTED";

export interface BffError {
  error: { code: BffErrorCode; message: string };
}

export const BFF_ERROR_STATUS: Record<BffErrorCode, number> = {
  INVALID_REQUEST: 400,
  PAYLOAD_TOO_LARGE: 413,
  SESSION_NOT_FOUND: 404,
  SESSION_LIMIT: 429,
  RATE_LIMITED: 429,
  SANDBOX_TIMEOUT: 504,
  NOT_FOUND: 404,
  INTERNAL: 500,
  NOT_IMPLEMENTED: 501,
};

export const BFF_ROUTES = {
  /** 201 CreateSessionResponse */
  createSession: "POST /api/sandbox/sessions",
  /** 200 SandboxExchange (body: SandboxRequest) */
  sendRequest: "POST /api/sandbox/sessions/:id/requests",
  /** 204 */
  deleteSession: "DELETE /api/sandbox/sessions/:id",
  /** 200 ExperimentsResponse */
  listExperiments: "GET /api/experiments",
} as const;
